import heapq
def main():
    n, m = map(int, input().split())
    adj = [[] for _ in range(n + 1)]; ind = [0] * (n + 1)
    for _ in range(m):
        a, b = map(int, input().split()); adj[a].append(b); ind[b] += 1
    h = [-i for i in range(1, n + 1) if ind[i] == 0]; heapq.heapify(h); out = []
    while h:
        u = -heapq.heappop(h); out.append(u)
        for v in adj[u]:
            ind[v] -= 1
            if ind[v] == 0: heapq.heappush(h, -v)
    print(*out)

from collections import deque
def main():
    n, m = map(int, input().split())
    g = [input().strip() for _ in range(n)]
    d = {}
    if g[0][0] != "#":
        d[(0, 0)] = 0
    q = deque(d)
    while q:
        x, y = q.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = x + dx, y + dy
            if 0 <= a < n and 0 <= b < m and g[a][b] != "#" and (a, b) not in d:
                d[(a, b)] = d[(x, y)] + 1; q.append((a, b))
    print(d.get((n - 1, m - 1), -1))

